// Structured data for Google rich results (organization, course list, FAQ).
function jsonLd() {
  const org = {
    "@type": "EducationalOrganization",
    "@id": `${SITE.url}/#organization`,
    name: SITE.name,
    url: SITE.url,
    logo: `${SITE.url}/logo.png`,
    ...(SITE.email && { email: SITE.email }),
    ...(SITE.phone && { telephone: SITE.phone }),
  };
  return {
    "@context": "https://schema.org",
    "@graph": [
      org,
      {
        "@type": "WebSite",
        "@id": `${SITE.url}/#website`,
        url: SITE.url,
        name: SITE.name,
        publisher: { "@id": org["@id"] },
        inLanguage: "en-IN",
      },
      {
        "@type": "ItemList",
        name: "Courses",
        itemListElement: COURSES.map((c, i) => ({
          "@type": "ListItem",
          position: i + 1,
          item: {
            "@type": "Course",
            name: c.name,
            description: `${c.tagline}. You'll learn: ${c.learn.join("; ")}.`,
            url: `${SITE.url}/#courses`,
            provider: { "@id": org["@id"] },
            educationalLevel: c.level,
            teaches: c.learn,
            offers: {
              "@type": "Offer",
              category: "Paid",
              price: SITE.price,
              priceCurrency: "INR",
              availability: "https://schema.org/LimitedAvailability",
              url: `${SITE.url}/#enroll`,
            },
            hasCourseInstance: {
              "@type": "CourseInstance",
              courseMode: "Online",
              ...(c.hours && { courseWorkload: `PT${c.hours}H` }),
            },
          },
        })),
      },
      {
        "@type": "FAQPage",
        mainEntity: FAQS.map((f) => ({
          "@type": "Question",
          name: f.q,
          acceptedAnswer: { "@type": "Answer", text: f.a },
        })),
      },
    ],
  };
}

